//! UFF parity tests against RDKit reference data
//! (`tests/data/uff/uff_reference.txt`, generated by
//! `tools/gen_uff_reference.py`).

use molecule_optimizer_rs::Molecule;
use molecule_optimizer_rs::ff::uff::{UffBuilder, uff_atom_types, uff_has_all_params};
use molecule_optimizer_rs::ff::{ForceField, ForceFieldBuilder};
use molecule_optimizer_rs::io::read_molfile;
use molecule_optimizer_rs::optim::{self, MinimizeOptions, MinimizeStatus, NoObserver};

#[derive(Debug, Default)]
struct OptRef {
    iters: usize,
    rc: i32,
    energy: f64,
    coords: Vec<[f64; 3]>,
}

#[derive(Debug, Default)]
struct Record {
    name: String,
    vdw_thresh: f64,
    ignore_interfrag: bool,
    molblock: String,
    coords: Vec<[f64; 3]>,
    types: Vec<String>,
    has_all: bool,
    energy: Option<f64>,
    grad: Vec<[f64; 3]>,
    opts: Vec<OptRef>,
}

fn parse_xyz(l: &str) -> [f64; 3] {
    let v: Vec<f64> = l.split_whitespace().map(|x| x.parse().unwrap()).collect();
    [v[0], v[1], v[2]]
}

fn load() -> Vec<Record> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/uff/uff_reference.txt");
    let text = std::fs::read_to_string(path).expect("fixture");
    let lines: Vec<&str> = text.lines().collect();
    let mut out = Vec::new();
    let mut k = 0;
    let mut cur = Record::default();
    while k < lines.len() {
        let l = lines[k];
        k += 1;
        if let Some(v) = l.strip_prefix("$NAME ") {
            cur = Record { name: v.to_string(), ..Default::default() };
        } else if let Some(v) = l.strip_prefix("$OPTS ") {
            let f: Vec<&str> = v.split_whitespace().collect();
            cur.vdw_thresh = f[0].parse().unwrap();
            cur.ignore_interfrag = f[1] == "1";
        } else if l == "$MOLBLOCK" {
            let mut mb = String::new();
            while lines[k] != "M  END" {
                mb.push_str(lines[k]);
                mb.push('\n');
                k += 1;
            }
            mb.push_str("M  END\n");
            k += 1;
            cur.molblock = mb;
        } else if let Some(v) = l.strip_prefix("$COORDS ") {
            let n: usize = v.trim().parse().unwrap();
            cur.coords = (0..n).map(|i| parse_xyz(lines[k + i])).collect();
            k += n;
        } else if let Some(v) = l.strip_prefix("$TYPES") {
            cur.types = v.split_whitespace().map(String::from).collect();
        } else if let Some(v) = l.strip_prefix("$HASALL ") {
            cur.has_all = v.trim() == "1";
        } else if let Some(v) = l.strip_prefix("$ENERGY ") {
            cur.energy = Some(v.trim().parse().unwrap());
        } else if l == "$GRAD" {
            let n = cur.coords.len();
            cur.grad = (0..n).map(|i| parse_xyz(lines[k + i])).collect();
            k += n;
        } else if let Some(v) = l.strip_prefix("$OPT ") {
            let f: Vec<&str> = v.split_whitespace().collect();
            let n = cur.coords.len();
            cur.opts.push(OptRef {
                iters: f[0].parse().unwrap(),
                rc: f[1].parse().unwrap(),
                energy: f[2].parse().unwrap(),
                coords: (0..n).map(|i| parse_xyz(lines[k + i])).collect(),
            });
            k += n;
        } else if l == "$END" {
            out.push(std::mem::take(&mut cur));
        }
    }
    out
}

fn mol_of(r: &Record) -> Molecule {
    let mut m = read_molfile(&r.molblock).unwrap_or_else(|e| panic!("{}: {e}", r.name));
    assert_eq!(m.num_atoms(), r.coords.len(), "{}", r.name);
    m.coords = r.coords.clone();
    m
}

fn builder(r: &Record) -> UffBuilder {
    UffBuilder { vdw_thresh: r.vdw_thresh, ignore_interfrag_interactions: r.ignore_interfrag }
}

fn rmsd(m: &Molecule, a: &[f64], b: &[[f64; 3]], heavy_only: bool) -> f64 {
    let mut s = 0.0;
    let mut n = 0;
    for (i, p) in b.iter().enumerate() {
        if heavy_only && m.atom(i).atomic_num <= 1 {
            continue;
        }
        for d in 0..3 {
            let x = a[3 * i + d] - p[d];
            s += x * x;
        }
        n += 1;
    }
    if n == 0 { 0.0 } else { (s / n as f64).sqrt() }
}

#[test]
fn atom_types_match_rdkit() {
    let recs = load();
    assert!(recs.len() > 300, "fixture has {} records", recs.len());
    let mut bad = Vec::new();
    for r in &recs {
        let m = mol_of(r);
        let t = uff_atom_types(&m).unwrap();
        if t != r.types {
            let diffs: Vec<String> = t
                .iter()
                .zip(&r.types)
                .enumerate()
                .filter(|(_, (a, b))| a != b)
                .map(|(i, (a, b))| format!("{i}:{a}!={b}"))
                .collect();
            bad.push(format!("{}: {}", r.name, diffs.join(",")));
        }
        assert_eq!(uff_has_all_params(&m), r.has_all, "{}", r.name);
    }
    assert!(bad.is_empty(), "{} type mismatches:\n{}", bad.len(), bad.join("\n"));
}

#[test]
fn energies_and_gradients_match_rdkit() {
    let recs = load();
    let mut bad = Vec::new();
    let (mut max_rel_e, mut max_rel_g) = (0.0f64, 0.0f64);
    let (mut n, mut exact_e, mut exact_g) = (0, 0, 0);
    for r in &recs {
        let Some(e_ref) = r.energy else { continue };
        let m = mol_of(r);
        let ff = builder(r).build(&m, &[]).unwrap();
        let pos = m.flat_coords();
        let mut g = vec![0.0; pos.len()];
        let e = ff.energy_grad(&pos, &mut g);
        n += 1;
        exact_e += (e == e_ref) as usize;
        if e != e_ref && std::env::var("UFF_VERBOSE").is_ok() {
            println!("  energy not bit-identical: {} ({e} vs {e_ref})", r.name);
        }
        exact_g += r.grad.iter().flatten().zip(&g).all(|(a, b)| a == b) as usize;
        let rel_e = (e - e_ref).abs() / e_ref.abs().max(1.0);
        max_rel_e = max_rel_e.max(rel_e);
        let gmax = r.grad.iter().flatten().fold(1.0f64, |a, &b| a.max(b.abs()));
        let dg = r.grad.iter().flatten().zip(&g).map(|(a, b)| (a - b).abs()).fold(0.0, f64::max) / gmax;
        max_rel_g = max_rel_g.max(dg);
        if rel_e > 1e-6 || dg > 1e-6 {
            bad.push(format!("{}: E {e} vs {e_ref} (rel {rel_e:.2e}), grad rel {dg:.2e}", r.name));
        }
    }
    println!(
        "{n} molecules: bit-identical energy {exact_e}, bit-identical gradient {exact_g};          max relative energy error {max_rel_e:.3e}, max relative gradient error {max_rel_g:.3e}"
    );
    assert!(bad.is_empty(), "{} energy/gradient mismatches:\n{}", bad.len(), bad.join("\n"));
}

#[test]
fn minimization_matches_rdkit() {
    let recs = load();
    let mut report = Vec::new();
    let mut n_total = 0;
    let mut n_ok = 0;
    let mut n_exact = 0;
    let (mut max_de, mut max_rmsd) = (0.0f64, 0.0f64);
    for r in &recs {
        if r.energy.is_none() {
            continue;
        }
        let m = mol_of(r);
        let ff = builder(r).build(&m, &[]).unwrap();
        for o in &r.opts {
            let mut pos = m.flat_coords();
            let opts = MinimizeOptions { max_iters: o.iters, ..Default::default() };
            let res = optim::minimize(&ff, &mut pos, &opts, &mut NoObserver);
            let rc = if res.status == MinimizeStatus::Converged { 0 } else { 1 };
            let de = (res.energy - o.energy).abs();
            let rm = rmsd(&m, &pos, &o.coords, true);
            n_total += 1;
            n_exact += (res.energy == o.energy && pos.iter().zip(o.coords.iter().flatten()).all(|(a, b)| a == b)) as usize;
            let ok = de <= 1e-4 && rm < 1e-3 && rc == o.rc;
            if ok {
                n_ok += 1;
                max_de = max_de.max(de);
                max_rmsd = max_rmsd.max(rm);
            } else {
                report.push(format!(
                    "{} (maxIters {}): E {} vs {} (dE {de:.2e}), heavy RMSD {rm:.2e}, rc {rc} vs {}",
                    r.name, o.iters, res.energy, o.energy, o.rc
                ));
            }
        }
    }
    println!("minimization: {n_exact}/{n_total} runs bit-identical to RDKit (energy and coordinates)");
    println!(
        "minimization parity: {n_ok}/{n_total} runs within dE<=1e-4 and heavy-atom RMSD<1e-3 \
         (max dE {max_de:.2e}, max RMSD {max_rmsd:.2e} among those)"
    );
    for l in &report {
        println!("  outlier: {l}");
    }
    assert!(n_ok as f64 >= 0.98 * n_total as f64, "{n_ok}/{n_total}:\n{}", report.join("\n"));
}

/// Debug helper:
/// `UFF_DUMP=name1,name2 cargo test --test uff_reference dump -- --ignored --nocapture`
#[test]
#[ignore]
fn dump() {
    let names = std::env::var("UFF_DUMP").unwrap_or_default();
    let names: Vec<&str> = names.split(',').collect();
    for r in load().iter().filter(|r| names.contains(&r.name.as_str())) {
        let m = mol_of(r);
        let t = uff_atom_types(&m).unwrap();
        println!("{}", r.name);
        for (i, a) in m.atoms().iter().enumerate() {
            if a.atomic_num == 1 {
                continue;
            }
            let bonds: Vec<String> = m
                .atom_bonds(i)
                .iter()
                .map(|&(o, b)| format!("({o}, {:?}, {})", m.bond(b).order, m.bond(b).is_conjugated))
                .collect();
            println!(
                "  {i} {} {:?} arom={} chg={} tv={} imph={} [{}] {} (ref {})",
                a.symbol(),
                a.hybridization,
                a.is_aromatic,
                a.formal_charge,
                m.total_valence(i),
                a.implicit_hs,
                bonds.join(", "),
                t[i],
                r.types[i]
            );
        }
    }
}
